/* ─────────────────────────────────────
   HAMBURGER
───────────────────────────────────── */
const hamBtn = document.getElementById('hamBtn');
const mobmenu = document.getElementById('mobmenu');
let menuOpen = false;

function openMob() {
  menuOpen = true;
  hamBtn.classList.add('open');
  hamBtn.setAttribute('aria-expanded','true');
  mobmenu.classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeMob() {
  menuOpen = false;
  hamBtn.classList.remove('open');
  hamBtn.setAttribute('aria-expanded','false');
  mobmenu.classList.remove('open');
  document.body.style.overflow = '';
}
hamBtn.addEventListener('click', () => menuOpen ? closeMob() : openMob());
document.addEventListener('keydown', e => { if (e.key === 'Escape' && menuOpen) closeMob(); });

/* ─────────────────────────────────────
   CURSOR
───────────────────────────────────── */
const cur  = document.getElementById('cur');
const crng = document.getElementById('crng');

// Only run on pointer:fine devices
if (window.matchMedia('(pointer:fine)').matches) {
  let mx = -200, my = -200, rx = -200, ry = -200, shown = false;

  document.addEventListener('mousemove', e => {
    mx = e.clientX; my = e.clientY;
    cur.style.left = mx + 'px';
    cur.style.top  = my + 'px';
    if (!shown) {
      shown = true;
      cur.style.opacity  = '1';
      crng.style.opacity = '1';
      rx = mx; ry = my;
      crng.style.left = rx + 'px';
      crng.style.top  = ry + 'px';
    }
  });

  (function loop() {
    rx += (mx - rx) * 0.11;
    ry += (my - ry) * 0.11;
    crng.style.left = rx + 'px';
    crng.style.top  = ry + 'px';
    requestAnimationFrame(loop);
  })();

  // Hover effects
  document.querySelectorAll('a, button, .svc-card, .pcard, .why-card, .glass, .ham').forEach(el => {
    el.addEventListener('mouseenter', () => {
      cur.style.width  = '20px';
      cur.style.height = '20px';
      cur.style.boxShadow = '0 0 20px rgba(179,19,23,1), 0 0 42px rgba(179,19,23,.6)';
      crng.style.width  = '58px';
      crng.style.height = '58px';
      crng.style.borderColor = 'rgba(179,19,23,.95)';
      crng.style.boxShadow   = '0 0 14px rgba(179,19,23,.4)';
    });
    el.addEventListener('mouseleave', () => {
      cur.style.width  = '12px';
      cur.style.height = '12px';
      cur.style.boxShadow = '0 0 12px rgba(179,19,23,.9), 0 0 24px rgba(179,19,23,.45)';
      crng.style.width  = '38px';
      crng.style.height = '38px';
      crng.style.borderColor = 'rgba(179,19,23,.55)';
      crng.style.boxShadow   = 'none';
    });
  });

  // Click burst
  document.addEventListener('mousedown', () => {
    cur.style.transform  = 'translate(-50%,-50%) scale(0.65)';
    crng.style.width     = '64px';
    crng.style.height    = '64px';
    crng.style.opacity   = '0.4';
  });
  document.addEventListener('mouseup', () => {
    cur.style.transform  = 'translate(-50%,-50%) scale(1)';
    crng.style.width     = '38px';
    crng.style.height    = '38px';
    crng.style.opacity   = '1';
  });
}

/* ─────────────────────────────────────
   PARTICLES
───────────────────────────────────── */
const pc = document.getElementById('particles');
for (let i = 0; i < 38; i++) {
  const p = document.createElement('div');
  p.className = 'dot';
  p.style.left = (Math.random() * 100) + 'vw';
  p.style.animationDuration = (Math.random() * 12 + 8) + 's';
  p.style.animationDelay    = (Math.random() * 16) + 's';
  const s = (Math.random() * 2.5 + .8) + 'px';
  p.style.width = p.style.height = s;
  pc.appendChild(p);
}

/* ─────────────────────────────────────
   NAVBAR SCROLL
───────────────────────────────────── */
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  navbar.style.background = window.scrollY > 60
    ? 'rgba(10,10,11,.92)'
    : 'rgba(10,10,11,.7)';
}, { passive: true });

/* ─────────────────────────────────────
   SCROLL REVEAL
───────────────────────────────────── */
// All sections are visible by default — animations are progressive enhancement
const animEls = document.querySelectorAll('.fade-up, .fade-left, .fade-right');

const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const delay = parseFloat(entry.target.dataset.delay || entry.target.style.transitionDelay || '0') * 1000;
      setTimeout(() => {
        entry.target.classList.add('show');
      }, delay);
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.08, rootMargin: '0px 0px -30px 0px' });

animEls.forEach(el => {
  const rect = el.getBoundingClientRect();
  // Already visible on load → animate immediately
  if (rect.top < window.innerHeight - 50) {
    const delay = parseFloat(el.style.transitionDelay || '0') * 1000;
    setTimeout(() => el.classList.add('show'), delay + 80);
  } else {
    revealObserver.observe(el);
  }
});

/* ─────────────────────────────────────
   TESTIMONIALS SLIDER
───────────────────────────────────── */
const tTrack  = document.getElementById('tTrack');
const tCards  = tTrack.querySelectorAll('.tcard');
const tDotsEl = document.getElementById('tDots');
let tCur = 0;

const tVis   = () => window.innerWidth > 900 ? 3 : window.innerWidth > 600 ? 2 : 1;
const tTotal = () => Math.ceil(tCards.length / tVis());

function buildDots() {
  tDotsEl.innerHTML = '';
  for (let i = 0; i < tTotal(); i++) {
    const d = document.createElement('button');
    d.className = 'tdot' + (i === tCur ? ' on' : '');
    d.setAttribute('aria-label', 'Slide ' + (i + 1));
    d.addEventListener('click', () => goTo(i));
    tDotsEl.appendChild(d);
  }
}

function goTo(idx) {
  tCur = ((idx % tTotal()) + tTotal()) % tTotal();
  const cw = tCards[0].offsetWidth + 20;
  tTrack.style.transform = `translateX(-${tCur * tVis() * cw}px)`;
  buildDots();
}

buildDots();
const autoSlide = setInterval(() => goTo(tCur + 1), 4800);

window.addEventListener('resize', () => { tCur = 0; goTo(0); }, { passive: true });

// Touch swipe
let tsX = 0;
tTrack.addEventListener('touchstart', e => { tsX = e.touches[0].clientX; }, { passive: true });
tTrack.addEventListener('touchend',   e => {
  const dx = e.changedTouches[0].clientX - tsX;
  if (Math.abs(dx) > 40) { clearInterval(autoSlide); goTo(tCur + (dx < 0 ? 1 : -1)); }
}, { passive: true });

/* ─────────────────────────────────────
   PARALLAX HERO (desktop only)
───────────────────────────────────── */
window.addEventListener('scroll', () => {
  if (window.innerWidth < 600) return;
  const y = window.scrollY;
  const bg = document.querySelector('.hero-bg');
  const gr = document.querySelector('.hero-grid-bg');
  if (bg) bg.style.transform = `translateY(${y * .33}px)`;
  if (gr) gr.style.transform = `translateY(${y * .17}px)`;
}, { passive: true });

/* ─────────────────────────────────────
   CONTACT FORM
───────────────────────────────────── */
document.getElementById('subBtn').addEventListener('click', function(e) {
  e.preventDefault();
  this.innerHTML = '✓ Message Sent!';
  this.style.background = '#197a19';
  this.style.boxShadow  = '0 8px 36px rgba(25,122,25,.5)';
  setTimeout(() => {
    this.innerHTML = 'Send Message <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>';
    this.style.background = '';
    this.style.boxShadow  = '';
  }, 3200);
});